/* k15_cutoff: for each point, count neighbours within radius r, scanning
 * points sorted by x and stopping once x is out of range.
 * IRREGULAR: points are clustered, so points inside dense clusters scan
 * far more neighbours than isolated ones (like molecular dynamics). */
#include <math.h>
#include <omp.h>
#include "common.h"

/* === KERNEL BEGIN === */
#define KBLK 64

static void kernel(long n, double r, const double *x, const double *y, int *nb) {
    const double r2 = r * r;
    const long nblk = (n + KBLK - 1) / KBLK;

    #pragma omp parallel for schedule(dynamic, 1)
    for (long b = 0; b < nblk; b++) {
        const long i0 = b * KBLK;
        const long i1 = (i0 + KBLK < n) ? i0 + KBLK : n;

        /* Initial window for i0 via binary search.
         * lo = first j in [0, i0] with x[i0] - x[j] <= r
         * hi = first j in [i0+1, n] with x[j] - x[i0] > r  (exclusive end) */
        const double x0 = x[i0];
        long a = 0, z = i0;
        while (a < z) {
            long m = a + (z - a) / 2;
            if (x0 - x[m] <= r) z = m; else a = m + 1;
        }
        long lo = a;
        a = i0 + 1; z = n;
        while (a < z) {
            long m = a + (z - a) / 2;
            if (x[m] - x0 <= r) a = m + 1; else z = m;
        }
        long hi = a;

        for (long i = i0; i < i1; i++) {
            const double xi = x[i], yi = y[i];
            while (lo < i && xi - x[lo] > r) lo++;
            if (hi < i + 1) hi = i + 1;
            while (hi < n && x[hi] - xi <= r) hi++;

            int c = 0;
            #pragma omp simd reduction(+:c)
            for (long j = lo; j < hi; j++) {
                double dx = x[j] - xi, dy = y[j] - yi;
                c += (dx * dx + dy * dy <= r2);
            }
            nb[i] = c - 1;   /* remove self (dx = dy = 0 always counted) */
        }
    }
}
/* === KERNEL END === */

static int cmp_x(const void *a, const void *b) {
    double d = ((const double *)a)[0] - ((const double *)b)[0];
    return (d > 0) - (d < 0);
}

int main(int argc, char **argv) {
    long n = arg_long(argc, argv, 1, 400000);
    double r = 0.002;
    double *xy = xmalloc(2 * n * sizeof *xy);
    rng_seed(15);
    /* 70% of points in 8 tight Gaussian-ish clusters, 30% spread uniformly */
    for (long i = 0; i < n; i++) {
        if (rng_unit() < 0.7) {
            int c = (int)(rng_next() % 8);
            double cx = 0.1 + 0.1 * c, cy = 0.5;
            double a = rng_unit() + rng_unit() + rng_unit() - 1.5;   /* ~bell */
            double b = rng_unit() + rng_unit() + rng_unit() - 1.5;
            xy[2 * i] = cx + 0.01 * a; xy[2 * i + 1] = cy + 0.01 * b;
        } else { xy[2 * i] = rng_unit(); xy[2 * i + 1] = rng_unit(); }
    }
    qsort(xy, n, 2 * sizeof *xy, cmp_x);   /* sort (x,y) pairs by x */
    double *x = xmalloc(n * sizeof *x), *y = xmalloc(n * sizeof *y);
    for (long i = 0; i < n; i++) { x[i] = xy[2 * i]; y[i] = xy[2 * i + 1]; }
    int *nb = xmalloc(n * sizeof *nb);

    double t0 = now_sec();
    kernel(n, r, x, y, nb);
    double t1 = now_sec();

    double sum = 0.0;
    for (long i = 0; i < n; i++) sum += nb[i];
    report("cutoff", t1 - t0, sum);
    free(xy); free(x); free(y); free(nb);
    return 0;
}

reply:
The main gain comes from making the inner loop vectorize. The original inner loops stop as soon as x leaves the radius, and a loop with an early exit like that can't be turned into SIMD code. Because x is sorted, the points within r in x always form one contiguous range [lo, hi) around i. As i increases, both ends of that range only move forward. So the window can be tracked with two moving pointers, and each point then needs one branch-free `omp simd` count over the window. Each block of points finds its starting window with a binary search, and blocks are handed out dynamically to balance the dense clusters against the sparse areas.

The result is identical to the serial version for three reasons:
- The window holds exactly the j values the two original scans visit, plus i itself.
- i always passes the distance test (dx = dy = 0), so subtracting 1 removes it exactly.
- (xi−xj)² equals (xj−xi)² exactly, so the backward-scan test gives the same answer.

